import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type CompassNeedleProps = Record<string, any>;

const CompassNeedle: React.FC<CompassNeedleProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 8,
  compassRingColor = "#27272a",
  compassMarkingsColor = "#71717a",
  compassCenterPinColor = "#e4e4e7",
  needleNorthColor = "#ef4444",
  needleSouthColor = "#f4f4f5",
  maxDriftAngle = 42,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive sizing based on the shortest dimension (optimized for 9:16 but flexible)
  const size = Math.min(width, height) * 0.8;

  // Background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timing ---
  // Phase 1: Steady (Frames 0 to steadyEndFrame)
  // Phase 2: Drift (steadyEndFrame to driftEndFrame)
  // Phase 3: Hold drifted angle (driftEndFrame to snapStartFrame)
  // Phase 4: Confident snap back (snapStartFrame onwards)

  const steadyEndFrame = Math.max(1, Math.floor(fps * durationInSeconds * 0.15));
  const driftEndFrame = Math.max(steadyEndFrame + 1, Math.floor(fps * durationInSeconds * 0.7));
  const snapStartFrame = Math.max(driftEndFrame + 1, Math.floor(fps * durationInSeconds * 0.85));

  // The subtle, almost imperceptible drift
  const driftRotation = interpolate(
    frame,
    [steadyEndFrame, driftEndFrame],
    [0, maxDriftAngle],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.33, 1, 0.68, 1), // Smooth ease out
    }
  );

  // The confident snap back to true north
  const snapProgress = spring({
    fps,
    frame: frame - snapStartFrame,
    config: {
      damping: 12,
      mass: 0.8,
      stiffness: 160,
      overshootClamping: false, // Allows a tiny magnetic wobble at the end
    },
  });

  // Combine animations based on the current phase
  let currentRotation = driftRotation;
  if (frame >= snapStartFrame) {
    // Interpolate from the max drifted angle back to 0 based on the spring progress
    currentRotation = interpolate(
      snapProgress,
      [0, 1],
      [maxDriftAngle, 0]
    );
  }

  // --- Static Compass Elements ---
  const tickMarks = Array.from({ length: 4 }).map((_, i) => {
    const angle = i * 90;

    return (
      <line
        key={i}
        x1="50"
        y1="4"
        x2="50"
        y2="12"
        stroke={compassMarkingsColor}
        strokeWidth="1.2"
        transform={`rotate(${angle} 50 50)`}
        style={{ transition: "none" }}
      />
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFamily,
      }}
    >
      <div
        style={{
          width: size,
          height: size,
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 100 100"
          style={{ width: "100%", height: "100%", overflow: "visible" }}
        >
          <defs>
            <filter id="needle-shadow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy="2" stdDeviation="1.5" floodColor="#000000" floodOpacity="0.4" />
            </filter>
            <filter id="glass-inset" x="-10%" y="-10%" width="120%" height="120%">
               <feDropShadow dx="0" dy="1" stdDeviation="2" floodColor="#000000" floodOpacity="0.5" />
            </filter>
          </defs>

          {/* Outer Ring */}
          <circle
            cx="50"
            cy="50"
            r="48"
            fill="none"
            stroke={compassRingColor}
            strokeWidth="2"
            filter="url(#glass-inset)"
          />
          <circle
            cx="50"
            cy="50"
            r="46"
            fill="none"
            stroke={backgroundColor}
            strokeWidth="0.5"
            opacity={0.5}
          />

          {/* Tick Marks */}
          {tickMarks}

          {/* Cardinal Directions */}
          <text x="50" y="22" fill={needleNorthColor} fontSize="7" fontWeight="800" textAnchor="middle" style={{ transition: "none" }}>N</text>

          {/* Rotating Needle Group */}
          <g
            style={{
              transform: `rotate(${currentRotation}deg)`,
              transformOrigin: "50px 50px",
              transition: "none",
            }}
            filter="url(#needle-shadow)"
          >
            {/* South Needle (Bottom half) */}
            <polygon
              points="50,90 44,50 56,50"
              fill={needleSouthColor}
              style={{ transition: "none" }}
            />
            
            {/* North Needle (Top half) */}
            <polygon
              points="50,10 44,50 56,50"
              fill={needleNorthColor}
              style={{ transition: "none" }}
            />
            
            {/* Left shading for 3D effect */}
            <polygon
              points="50,10 44,50 50,50"
              fill="#000000"
              opacity={0.15}
              style={{ transition: "none", mixBlendMode: "multiply" }}
            />
            <polygon
              points="50,90 44,50 50,50"
              fill="#000000"
              opacity={0.15}
              style={{ transition: "none", mixBlendMode: "multiply" }}
            />

            {/* Center Pin */}
            <circle
              cx="50"
              cy="50"
              r="2.5"
              fill={compassCenterPinColor}
              style={{ transition: "none" }}
            />
            <circle
              cx="50"
              cy="50"
              r="1"
              fill={compassRingColor}
              style={{ transition: "none" }}
            />
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default CompassNeedle;